const cb = $json.callback_query.data; // approve_ORD10453 or reject_ORD10453
const orderId = cb.split('_').slice(1).join('_');
return [{
  json: {
    order_id: orderId,
    approver_chat_id: $json.callback_query.message.chat.id,
    approver_message_id: $json.callback_query.message.message_id
  }
}];

const msg = $json.message || {};
const text = msg.text || '';
const parts = text.split('|');
const orderId = (parts[0] || '').trim();
const messageText = (parts.slice(1).join('|') || '').trim();
const fromUser = msg.from || {};
const customerName = [fromUser.first_name, fromUser.last_name].filter(Boolean).join(' ') || 'Unknown Customer';

return [{
  json: {
    order_id: orderId,
    customer_name: customerName,
    customer_phone: '',
    customer_chat_id: String(msg.chat ? msg.chat.id : ''),
    message_text: messageText,
    image_url: '',
    received_at: new Date().toISOString(),
    support_lead_chat_id: 'YOUR_SUPPORT_LEAD_CHAT_ID',
    warehouse_chat_id: 'YOUR_WAREHOUSE_CHAT_ID',
    ops_manager_chat_id: 'YOUR_OPS_MANAGER_CHAT_ID'
  }
}];

const normalized = $('Normalize Complaint Input').first().json;
const orderRows = $('Lookup Order Details').all();
const order = orderRows.length ? orderRows[0].json : {};
const historyRows = $input.all();

const now = new Date();
const thisMonthCount = historyRows.filter(r => {
  const d = new Date(r.json.timestamp || r.json.received_at || 0);
  return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
}).length;

const text = (normalized.message_text || '').toLowerCase();
const orderedSku = order.ordered_sku || '';
const packedSku = order.packed_sku || '';
const skuMismatch = orderedSku && packedSku && orderedSku !== packedSku;

let issueType = 'other';
if (/damaged|broken|crushed|missing|not received|empty box/.test(text)) {
  issueType = 'damaged_missing';
} else if (skuMismatch || /wrong item|different item|not what i ordered/.test(text)) {
  issueType = 'wrong_item';
}

const orderValue = Number(order.order_value || 0);
const isHighValue = orderValue > 500;
const isRepeatOffender = (thisMonthCount + 1) >= 3;

let liability = 'unknown';
if (issueType === 'wrong_item') {
  liability = 'packing';
} else if (issueType === 'damaged_missing') {
  liability = /courier|delivery guy|driver|transit/.test(text) ? 'courier' : 'packing';
}

return [{
  json: {
    ...normalized,
    customer_name: order.customer_name || normalized.customer_name,
    customer_phone: order.customer_phone || normalized.customer_phone,
    ordered_sku: orderedSku,
    packed_sku: packedSku,
    packer_name: order.packer_name || 'unknown',
    courier_name: order.courier_name || 'unknown',
    order_value: orderValue,
    issue_type: issueType,
    is_high_value: isHighValue,
    complaints_this_month: thisMonthCount + 1,
    is_repeat_offender: isRepeatOffender,
    liability: liability
  }
}];

const data = $('Determine Issue Type and Repeat Offender').first().json;

let sentiment = 'neutral';
try {
  const raw = $input.first().json.message?.content || $input.first().json.content || $input.first().json.text || '{}';
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  sentiment = parsed.sentiment || 'neutral';
} catch (e) {
  sentiment = 'neutral';
}

let route = 'escalate_support';

if (data.is_repeat_offender) {
  route = 'escalate_ops';
} else if (sentiment === 'angry' || sentiment === 'frustrated') {
  route = 'escalate_support';
} else if (data.issue_type === 'damaged_missing') {
  route = 'escalate_warehouse';
} else if (data.issue_type === 'wrong_item' && !data.is_high_value) {
  route = 'auto_approve';
} else if (data.issue_type === 'wrong_item' && data.is_high_value) {
  route = 'escalate_support';
}

return [{
  json: {
    ...data,
    sentiment,
    route
  }
}];

