const rows = $input.all();
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const recent = rows.filter(r => {
  const d = new Date(r.json.timestamp || 0);
  return d >= weekAgo && (r.json.issue_type === 'wrong_item' || r.json.issue_type === 'damaged_missing');
});
const original = $('Log Escalation - Warehouse').first().json;
return [{
  json: {
    ...original,
    packer_complaints_this_week: recent.length,
    packer_pattern_flag: recent.length >= 3
  }
}];

